import {rect,star} from './art.js';
// Project-owned inline asset: no network request, rendered on a 192 x 64 pixel grid.
const logo=typeof Image==='undefined'?null:new Image();let bitmap=null;
export const logoReady=logo?new Promise(resolve=>{logo.onload=()=>{bitmap=document.createElement('canvas');bitmap.width=192;bitmap.height=64;const c=bitmap.getContext('2d');c.imageSmoothingEnabled=false;c.drawImage(logo,0,0,192,64);resolve();};logo.onerror=()=>resolve();logo.src='data:image/png;base64,';}):Promise.resolve();
export function drawGoalLogo(c,x,y){rect(c,x-2,y-2,196,68,'gold');rect(c,x,y,192,64,'black');if(bitmap&&c.drawImage){c.imageSmoothingEnabled=false;c.drawImage(bitmap,Math.round(x),Math.round(y));}else star(c,x+76,y+12,40,'yellow');}
